fn scan(values: Vec[int]) {
    for value in values { println(value) }
}
fn main() {
    var values = [1, 2]
    scan(values)
    println(values.len())
}

fn scan(values: inout Vec[int]) {
    for value in values { println(value) }
    values.push(3)
}
fn main() {
    var values = [1, 2]
    scan(&values)
    println(values.len())
}

fn lower(value: int) -> int { println("L")
    return value }
fn upper(value: int) -> int { println("U")
    return value }
fn main() {
    for value in lower(1)..upper(3) { println(value) }
    for value in lower(3)..upper(1) { println(value) }
    println("done")
}

